from typing import Any, Dict, List, Optional, Set, Tuple
import time


class Job:
    """Provide job behavior."""

    def __init__(self, id: str, dependencies: Set[str], priority: int):
        self.id = id
        self.dependencies = dependencies
        self.priority = priority
        self.status = 'PENDING'
        self.start_time = None
        self.end_time = None
        self.attempts = 0

    def run(self) -> None:
        """Run."""
        time.sleep(1)
        self.status = 'COMPLETED'


class Scheduler:
    """Provide scheduler behavior."""

    def __init__(self, max_workers: int):
        self.max_workers = max_workers
        self.jobs = {}
        self.dependencies = {}
        self.worker_queue = []
        self.cycles_detected = False

    def submit_job(self, job_id: str, dependencies: Set[str], priority: int) -> None:
        """Submit job."""
        if self.cycles_detected:
            raise ValueError('Cycles detected in the job graph')
        if job_id in self.jobs:
            raise ValueError(f'Job {job_id} already exists')
        for dep in dependencies:
            if dep not in self.dependencies:
                raise ValueError(f'Dependency {dep} does not exist')
        new_job = Job(job_id, dependencies, priority)
        self.jobs[job_id] = new_job
        for dep in dependencies:
            self.dependencies.setdefault(dep, set()).add(job_id)
        self.worker_queue.append(new_job)

    def pause_job(self, job_id: str) -> None:
        """Pause job."""
        if job_id not in self.jobs:
            raise ValueError(f'Job {job_id} does not exist')
        self.jobs[job_id].status = 'PAUSED'

    def resume_job(self, job_id: str) -> None:
        """Resume job."""
        if job_id not in self.jobs:
            raise ValueError(f'Job {job_id} does not exist')
        if self.jobs[job_id].status == 'PENDING':
            self.worker_queue.append(self.jobs[job_id])
        elif self.jobs[job_id].status == 'PAUSED':
            self.jobs[job_id].status = 'PENDING'
            self.worker_queue.append(self.jobs[job_id])

    def cancel_job(self, job_id: str) -> None:
        """Cancel job."""
        if job_id not in self.jobs:
            raise ValueError(f'Job {job_id} does not exist')
        self.jobs[job_id].status = 'CANCELLED'

    def status_snapshot(self) -> Dict[str, Any]:
        """Status snapshot."""
        return {job.id: {'status': job.status, 'start_time': job.start_time, 'end_time': job.end_time} for job in self.jobs.values()}

    def deterministic_replay(self) -> None:
        """Deterministic replay."""
        for job in sorted(self.worker_queue, key=lambda x: (-x.priority, x.id)):
            if job.status == 'PENDING':
                job.run()
                job.start_time = time.time()
                job.end_time = time.time()
                job.attempts += 1


